package com.stockflow.document.application;
import com.stockflow.document.domain.FinancialExtractionDraft; import org.springframework.stereotype.Service; import java.util.UUID;
@Service public class GetFinancialExtractionDraft { private final DocumentRepository documents; private final FinancialExtractionDraftRepository drafts; private final DocumentActorAuthorizer authorizer; public GetFinancialExtractionDraft(DocumentRepository d,FinancialExtractionDraftRepository r,DocumentActorAuthorizer a){documents=d;drafts=r;authorizer=a;} public FinancialExtractionDraft get(UUID actorId,UUID documentId){var d=documents.findActiveById(documentId).orElseThrow(DocumentNotFoundException::new);authorizer.requireOwnerOrAdmin(actorId,d);return drafts.findByDocumentId(documentId).orElseThrow(FinancialExtractionNotFoundException::new);} }
